// Package webui embeds the static build of the admin WebUI (Phase 5, D13)
// into the Go binary. go:embed only resolves paths relative to the directory
// of the .go file, which is why this package lives inside webui/ (next to
// the Vite project) instead of internal/ like the rest of the core. See
// docs/api-contract.md, section "/api/v1 prefix and embedded WebUI", and D13
// (elaboration "Architecture correction", docs/decisions/).
package webui

import "embed"

// DistFS is the content of dist/ (generated by `npm run build`) embedded in
// the binary. cmd/m3m0s/serve.go uses fs.Sub(DistFS, "dist") to strip the
// "dist/" prefix that go:embed preserves in the path, so files are served
// from the right root.
//
//go:embed all:dist
var DistFS embed.FS
